/** English Language Proficiency Standards (19 TAC §74.4(c)), generated by scripts/build-elps.py. */
import { queryRegexes } from "./teks";

export type ElpsDomain = "strategies" | "listening" | "speaking" | "reading" | "writing";

export interface ElpsItem {
  id: string; // "74.4:3E"
  code: string; // "ELPS 3E"
  domain: ElpsDomain;
  domainLabel: string;
  text: string;
  iwill: string;
  cite: string;
}

export interface ElpsData {
  source: string;
  retrieved: string;
  items: ElpsItem[];
  plds: Pld[];
}

export const ELPS_DOMAINS: { value: ElpsDomain | "all"; label: string; emoji: string }[] = [
  { value: "all", label: "All", emoji: "🌐" },
  { value: "listening", label: "Listening", emoji: "👂" },
  { value: "speaking", label: "Speaking", emoji: "🗣️" },
  { value: "reading", label: "Reading", emoji: "📖" },
  { value: "writing", label: "Writing", emoji: "✏️" },
  { value: "strategies", label: "Learning Strategies", emoji: "🧠" },
];

/** Sentence-stem ideas by domain, offered when adding a stem to an "I will" goal. */
export const STEM_IDEAS: Record<ElpsDomain, string[]> = {
  listening: ["I heard ___.", "The speaker said ___, which means ___."],
  speaking: ["I think ___ because ___.", "I agree/disagree with ___ because ___.", "First ___, then ___."],
  reading: ["The text says ___.", "I can tell ___ because the text states ___."],
  writing: ["In my opinion, ___ because ___.", "One example is ___."],
  strategies: ["This reminds me of ___.", "Another way to say ___ is ___."],
};

let cache: Promise<ElpsData> | null = null;
export function loadElps(): Promise<ElpsData> {
  if (!cache) cache = import("@/data/elps.json").then((m) => (m.default ?? m) as unknown as ElpsData);
  return cache;
}

export function searchElps(items: ElpsItem[], domain: ElpsDomain | "all", query: string): ElpsItem[] {
  const pool = items.filter((i) => domain === "all" || i.domain === domain);
  const raw = query.trim().toLowerCase();
  if (!raw) return pool;
  const code = raw.replace(/^elps\s*/, "").replace(/\s+/g, "").toUpperCase();
  const byCode = pool.filter((i) => i.code.endsWith(` ${code}`));
  if (/^[1-5][A-K]$/.test(code) && byCode.length) return byCode;
  const res = queryRegexes(raw);
  return pool.filter((i) => res.every((r) => r.test(`${i.code} ${i.domainLabel} ${i.text}`)));
}

/* ------------------------------------------------------------------ Proficiency levels */

export type ProficiencyLevel = "beginning" | "intermediate" | "advanced" | "advancedHigh";

export const LEVELS: { value: ProficiencyLevel; label: string; short: string; color: string }[] = [
  { value: "beginning", label: "Beginning", short: "B", color: "#e5484d" },
  { value: "intermediate", label: "Intermediate", short: "I", color: "#f76b15" },
  { value: "advanced", label: "Advanced", short: "A", color: "#0c8ce9" },
  { value: "advancedHigh", label: "Advanced High", short: "AH", color: "#2bb673" },
];

/** Official proficiency level descriptor (19 TAC §74.4(d)). */
export interface Pld {
  domain: "listening" | "speaking" | "reading" | "writing";
  band: "K-12" | "K-1" | "2-12";
  level: ProficiencyLevel;
  summary: string;
  bullets: string[];
  cite: string;
}

export type PldBand = "K-1" | "2-12";

/** Descriptor for a domain/level; reading and writing differ for K–1 vs 2–12. */
export function findPld(plds: Pld[], domain: string, level: ProficiencyLevel, band: PldBand): Pld | null {
  return plds.find((p) => p.domain === domain && p.level === level && (p.band === "K-12" || p.band === band)) ?? null;
}

